    /// <summary>
    /// MPJ_3747_AltVendorPayee 06/03/2021 Nathan Ciantar
    /// returns the field found
    /// </summary>
    /// <returns>metOrganisation</returns>
    public display METOrganisation metOrganisation()
    {
        METOrganisation metOrganisation = '';

        metOrganisation = VendBankAccount::find(this.AccountNum, this.BankAccount).METVendorBankOrganisation;

        return metOrganisation;

    }

    /// <summary>
    /// MPJ_3747_AltVendorPayee 06/03/2021 Nathan Ciantar
    /// returns the field found
    /// </summary>
    /// <returns>metSupplyChain</returns>
    public display METSupplyChain metSupplyChain()
    {
        METSupplyChain metSupplyChain;

        metSupplyChain = VendBankAccount::find(this.AccountNum, this.BankAccount).METAltVendorPayee;

        return metSupplyChain;

    }
